	if (this.stopped) {
		return;
	}
	this.stopped = true;
	if (this.animation) {
		this.win.cancelAnimationFrame(this.animation);
	}
	this.finishText && this.finishText();
	for (var i = 0; i < this.listeners.length; i++) {
		var l = this.listeners[i];
		l[0].removeEventListener(l[1], l[2], l[3]);
	}
