};

methods.stopPresentation = function() {
	if (this.player) {
		this.player.stop();
	}
};

methods.afterPresentation = function() {
	this.player = null;
	this.presenting = false;
	this.presentIndex = -1;
	if (this.savedCamera && !this.destroyed) {
		this.animateCamera(this.savedCamera, 600);
	}
	if (!this.destroyed) {
		this.updateUi();
		this.renderSelection();
		this.scheduleRender();
