	this.presentMenu = el("div", {"class": "pb-topbar pb-chrome", role: "toolbar", "aria-label": "Presentation"}, [
		Dom.button(doc, "play", "Present (from the first step)", function() { self.startPresentation(0); }, "pb-btn-primary"),
		this.stepsButton,
		this.layersButton
	]);
