	stroke-width: 4px;
	stroke-linejoin: round;
}

/*** Shapes ***/

.pb-shape .pb-hit { cursor: move; }
.pb-root[data-pb-tool="eraser"] .pb-shape .pb-hit { cursor: cell; }
.pb-shape-sticky { filter: drop-shadow(0 4px 6px rgba(0,0,0,.18)); }
.pb-frame-label {
	font-size: 15px;
	font-weight: 600;
}

.pb-shape-text {
	box-sizing: border-box;
	width: 100%;
	height: 100%;
	display: flex;
	align-items: center;
	justify-content: center;
	text-align: center;
	white-space: pre-wrap;
	overflow-wrap: anywhere;
	line-height: 1.25;
	padding: .3em;
	overflow: hidden;
	font-family: inherit;
}

