.pb-text-editor {
	position: absolute;
	z-index: 30;
	box-sizing: border-box;
	margin: 0;
	padding: .2em .3em;
	border: 2px solid var(--pb-accent);
	border-radius: 4px;
	background: color-mix(in srgb, var(--pb-panel) 92%, transparent);
	font-family: inherit;
	line-height: 1.25;
	resize: both;
	outline: none;
}
.pb-text-editor-sticky { background: #fde68a; font-family: "Segoe Print", "Bradley Hand", "Comic Sans MS", cursive, sans-serif; }

/*** Chrome ***/

.pb-chrome {
	position: absolute;
	z-index: 20;
	-webkit-user-select: none;
	user-select: none;
}

.pb-toolbar,
.pb-topbar,
.pb-zoombar,
.pb-context,
.pb-popup,
.pb-steps {
	background: color-mix(in srgb, var(--pb-panel) 88%, transparent);
	backdrop-filter: blur(10px);
	-webkit-backdrop-filter: blur(10px);
	border: 1px solid var(--pb-border);
	border-radius: 12px;
	box-shadow: 0 6px 22px rgba(0,0,0,.14);
}

.pb-toolbar {
	left: 10px;
	top: 50%;
	transform: translateY(-50%);
	display: flex;
	flex-direction: column;
	gap: 2px;
	padding: 4px;
	max-height: calc(100% - 20px);
	overflow-y: auto;
	scrollbar-width: none;
}

.pb-group {
	display: grid;
	grid-template-columns: repeat(2, 34px);
	gap: 2px;
	padding-bottom: 4px;
	border-bottom: 1px solid var(--pb-border);
}
