.pb-dock-sep {
	height: 1px;
	margin: 3px 4px;
	background: var(--pb-border);
}
.pb-btn.pb-has-flyout { position: relative; }
.pb-btn.pb-has-flyout::after {
	content: "";
	position: absolute;
	right: 3px;
	bottom: 3px;
	border: 3px solid transparent;
	border-right-color: currentColor;
