/* Flyout to the right of the dock */
.pb-flyout {
	display: none;
	flex-direction: column;
	gap: 8px;
	padding: 8px;
	min-width: 190px;
	background: color-mix(in srgb, var(--pb-panel) 92%, transparent);
	backdrop-filter: blur(10px);
	-webkit-backdrop-filter: blur(10px);
	border: 1px solid var(--pb-border);
	border-radius: 12px;
	box-shadow: 0 6px 22px rgba(0,0,0,.14);
