	left: 50%;
	bottom: 10px;
	transform: translateX(-50%);
	padding: 4px 12px;
	border-radius: 20px;
	font-size: 12px;
	color: <<colour alert-foreground>>;
	background: <<colour alert-background>>;
	border: 1px solid <<colour alert-border>>;
}

.pb-context {
	display: flex;
	gap: 2px;
	padding: 3px;
}

.pb-popup {
	width: 240px;
	max-height: calc(100% - 16px);
	display: flex;
	flex-direction: column;
	padding: 8px;
	box-sizing: border-box;
}

.pb-popup-head {
	display: flex;
	align-items: center;
	justify-content: space-between;
	gap: 8px;
	margin-bottom: 6px;
}

.pb-popup-sub {
	font-size: 12px;
	color: var(--pb-muted);
	margin: -4px 0 6px;
	overflow-wrap: anywhere;
}

.pb-popup-foot {
	display: flex;
	flex-wrap: wrap;
	gap: 6px;
	margin-top: 8px;
}

.pb-chooser-list {
	overflow-y: auto;
	min-height: 0;
}

.pb-chooser-row {
	display: flex;
	align-items: center;
	justify-content: space-between;
	padding: 1px 2px;
	border-radius: 6px;
}
.pb-chooser-row.pb-chosen { font-weight: 600; }
.pb-chooser-row label { flex: 1; cursor: pointer; padding: 4px 2px; overflow-wrap: anywhere; }

.pb-textbtn {
	border: 1px solid var(--pb-border);
	background: var(--pb-panel);
	color: var(--pb-fg);
	border-radius: 8px;
	padding: 4px 10px;
	cursor: pointer;
	font-size: 13px;
}
.pb-textbtn:hover:not(:disabled) { border-color: var(--pb-accent); }
.pb-textbtn:disabled { opacity: .55; cursor: default; }
.pb-textbtn-primary { background: var(--pb-accent); border-color: var(--pb-accent); color: <<colour background>>; }

.pb-field-row {
	display: flex;
	flex-direction: column;
	gap: 3px;
	margin: 4px 0 8px;
	font-size: 13px;
}
.pb-select {
	width: 100%;
	padding: 4px;
	border: 1px solid var(--pb-border);
	border-radius: 6px;
	background: var(--pb-panel);
	color: var(--pb-fg);
}

.pb-steps {
	top: 58px;
	right: 10px;
	bottom: 58px;
	width: 280px;
	display: none;
	flex-direction: column;
	padding: 10px;
	box-sizing: border-box;
}
.pb-steps.pb-open { display: flex; }

.pb-step-list {
	list-style: none;
	margin: 0;
	padding: 0;
	overflow-y: auto;
	flex: 1;
	min-height: 0;
	scrollbar-width: thin;
	scrollbar-color: color-mix(in srgb, var(--pb-fg) 22%, transparent) transparent;
}
.pb-step-list::-webkit-scrollbar { width: 6px; }
.pb-step-list::-webkit-scrollbar-track { background: transparent; }
.pb-step-list::-webkit-scrollbar-thumb {
	background: color-mix(in srgb, var(--pb-fg) 22%, transparent);
	border-radius: 3px;
}
.pb-step-list::-webkit-scrollbar-thumb:hover { background: color-mix(in srgb, var(--pb-fg) 40%, transparent); }

.pb-step {
	display: flex;
	align-items: center;
	gap: 1px;
	border-radius: 8px;
	padding: 2px;
}
.pb-step:hover { background: color-mix(in srgb, var(--pb-fg) 6%, transparent); }
.pb-step.pb-current { background: color-mix(in srgb, var(--pb-accent) 18%, transparent); }
.pb-step.pb-missing { opacity: .5; }
.pb-shape-hidden { display: none; }
.pb-grip {
	flex: none;
	display: inline-flex;
	align-items: center;
	justify-content: center;
	width: 18px;
	height: 26px;
	color: var(--pb-muted);
	cursor: grab;
	touch-action: none;
}
.pb-grip .pb-icon { width: 16px; height: 16px; stroke-width: 3; }
.pb-step.pb-sorting { opacity: .45; }
.pb-step { padding-left: calc(2px + var(--pb-level, 0) * 16px); }
.pb-step .pb-step-indent,
.pb-step .pb-step-outdent { display: none; }
.pb-step:hover .pb-step-indent,
.pb-step:hover .pb-step-outdent { display: inline-flex; }

/*** Stories ***/

.pb-story-row {
	display: flex;
	align-items: center;
	gap: 6px;
	margin: 0 0 8px;
}
.pb-story-select {
	flex: 1;
	min-width: 0;
	padding: 4px;
	border: 1px solid var(--pb-border);
	border-radius: 6px;
	background: var(--pb-panel);
	color: var(--pb-fg);
	font-weight: 600;
}
.pb-story-dot {
	flex: none;
	width: 12px;
	height: 12px;
	border-radius: 50%;
}
.pb-story-name, .pb-story-tiddler-name { flex: 1; min-width: 0; }
.pb-story-color {
	flex: none;
	width: 28px;
	height: 28px;
	padding: 0;
	border: 1px solid var(--pb-border);
	border-radius: 6px;
	background: none;
	cursor: pointer;
}
.pb-story-width { flex: 1; min-width: 0; }
.pb-story-head { gap: 2px; }
.pb-story-head .pb-story-dot { margin-right: 4px; }
.pb-story-head .pb-story-select { margin-right: 2px; }
.pb-story-eye.pb-off { color: var(--pb-muted); }
.pb-story-settings {
	display: flex;
	flex-direction: column;
	align-items: flex-start;
	gap: 6px;
	margin: 0 0 8px;
	padding: 8px;
	border: 1px solid var(--pb-border);
	border-radius: 8px;
	background: var(--pb-panel);
}
.pb-story-field {
	display: flex;
	align-items: center;
	gap: 6px;
	align-self: stretch;
}
.pb-story-field > span:first-child {
	flex: none;
	width: 48px;
	color: var(--pb-muted);
	font-size: 12px;
}
.pb-story-delete { color: #c0392b; }
.pb-story-error { color: #c0392b; font-size: 12px; }
.pb-story-buttons { flex-wrap: wrap; }
.pb-story-link {
	display: inline-flex;
	align-items: center;
	gap: 4px;
	min-width: 0;
	border: none;
	background: none;
	color: var(--pb-accent);
	cursor: pointer;
	font-size: 13px;
	overflow: hidden;
	text-overflow: ellipsis;
	white-space: nowrap;
}
.pb-story-link .pb-icon { width: 16px; height: 16px; flex: none; }

.pb-root svg.pb-layer-path .pb-thread-line {
	fill: none;
	stroke-linecap: round;
	stroke-linejoin: round;
	opacity: .85;
	vector-effect: non-scaling-stroke;
}
.pb-thread-mark circle {
	stroke: var(--pb-panel);
	stroke-width: 2px;
}
.pb-thread-mark text {
	fill: #fff;
	font-size: 12px;
	font-weight: 700;
	font-family: inherit;
}
.pb-card.pb-in-story {
	box-shadow: 0 0 0 3px var(--pb-story-color, #e0503f), 0 6px 18px rgba(0,0,0,.10);
}
.pb-root.pb-presenting .pb-layer-path,
.pb-root.pb-presenting .pb-layer-path-marks { display: none; }
.pb-drop-marker {
	height: 3px;
	margin: 1px 4px;
	border-radius: 2px;
	background: var(--pb-accent);
	list-style: none;
}
.pb-layer-cards {
	display: flex;
	align-items: center;
	gap: 8px;
	margin: 4px 0;
	padding: 5px 8px;
	border-radius: 8px;
	font-size: 13px;
	color: var(--pb-muted);
	background: color-mix(in srgb, var(--pb-fg) 6%, transparent);
	list-style: none;
}
.pb-layer-cards .pb-icon { width: 16px; height: 16px; }
.pb-layer-swatch {
	flex: none;
	width: 12px;
	height: 12px;
	border-radius: 3px;
	border: 1px solid var(--pb-border);
	background: var(--pb-swatch);
}

.pb-step-name {
	flex: 1;
	display: flex;
	align-items: center;
	gap: 8px;
	min-width: 0;
	border: none;
	background: transparent;
	color: var(--pb-fg);
	text-align: left;
	padding: 4px;
	cursor: pointer;
}

.pb-step-title {
	overflow: hidden;
	text-overflow: ellipsis;
	white-space: nowrap;
}

.pb-step-kind {
	flex: none;
	display: inline-flex;
	align-items: center;
	justify-content: center;
	width: 22px;
	height: 22px;
	border-radius: 6px;
	font-size: 12px;
	font-weight: 700;
	color: #fff;
	background: #6366f1;
}
.pb-step-kind-card { background: var(--pb-accent); }
.pb-step-kind-shape { background: #10b981; }
.pb-step-kind-view { background: #f59e0b; }

.pb-empty {
	color: var(--pb-muted);
	font-size: 13px;
	line-height: 1.45;
}

.pb-root.pb-readonly .pb-toolbar { display: none; }

/*** Presentation ***/

/* Picture on the board (background "on the board") */
.pb-root img.pb-board-image {
	position: absolute;
	max-width: none;
	pointer-events: none;
	-webkit-user-select: none;
	user-select: none;
}

/* Filter (Lupe) */
.pb-filtered-out { display: none !important; }
.pb-filter-input { flex: 1; min-width: 0; }
.pb-filter-foot { justify-content: space-between; font-size: 12px; color: var(--pb-muted); }
.pb-btn.pb-filtering { box-shadow: inset 0 0 0 2px var(--pb-accent); }

/* TiddlyWiki's top bar (sidebar toggle) would show through the
   fullscreen board. */
html:has(.pb-root.pb-fullscreen) .tc-topbar { display: none; }

/* Board fullscreen: the page is fullscreen and the board covers it, below
   TiddlyWiki's own dialogs (z-index 900+). */
.pb-root.pb-fullscreen {
	position: fixed;
	inset: 0;
	z-index: 850;
	width: 100vw;
	height: 100vh;
	background-color: var(--pb-bg);
}

.pb-root.pb-presenting {
	position: fixed;
	inset: 0;
	z-index: 10000;
	width: 100vw;
	height: 100vh;
}

.pb-root.pb-presenting .pb-toolbar,
.pb-root.pb-presenting .pb-topbar,
.pb-root.pb-presenting .pb-zoombar,
.pb-root.pb-presenting .pb-context,
.pb-root.pb-presenting .pb-notice,
.pb-root.pb-presenting .pb-steps,
.pb-root.pb-presenting .pb-popup,
.pb-root.pb-presenting .pb-card-tools,
.pb-root.pb-presenting .pb-card-resize,
.pb-root.pb-presenting .pb-card-connector,
.pb-root.pb-presenting .pb-shape-frame { display: none; }

.pb-root.pb-presenting .pb-card.pb-selected { outline: none; }
.pb-root.pb-presenting .pb-card { transition: box-shadow .4s ease, opacity .4s ease; }
.pb-root.pb-presenting .pb-card.pb-spotlight { box-shadow: 0 0 0 3px var(--pb-accent), 0 18px 48px rgba(0,0,0,.25); }

.pb-present-ui {
	inset: 0;
	pointer-events: none;
}

.pb-zone {
	position: absolute;
	top: 0;
	bottom: 70px;
	width: 9%;
	pointer-events: auto;
	cursor: pointer;
}
.pb-zone-left { left: 0; cursor: w-resize; }
.pb-zone-right { right: 0; cursor: e-resize; }

.pb-present-progress {
	position: absolute;
	left: 50%;
	bottom: 16px;
	transform: translateX(-50%);
	display: flex;
	flex-direction: column;
	align-items: center;
	pointer-events: auto;
}

.pb-present-bar {
	display: flex;
	align-items: center;
	gap: 4px;
	padding: 4px;
	border-radius: 24px;
	pointer-events: auto;
	color: #fff;
	background: rgba(20, 20, 24, .55);
	backdrop-filter: blur(8px);
	-webkit-backdrop-filter: blur(8px);
	opacity: .35;
	transition: opacity .2s ease;
}
.pb-present-bar:hover,
.pb-present-progress.pb-open .pb-present-bar { opacity: 1; }
.pb-present-info { cursor: pointer; border-radius: 14px; padding: 2px 10px; }
.pb-present-info:hover { background: rgba(255,255,255,.14); }

/* Stack of all stops, last on top; opens from the counter. */
.pb-present-stack {
	display: flex;
	flex-direction: column;
	align-items: center;
	gap: 3px;
	max-height: 0;
	overflow: hidden;
	opacity: 0;
	transition: opacity .15s ease;
}
.pb-present-progress.pb-open .pb-present-stack {
	max-height: 55vh;
	overflow-y: auto;
	opacity: 1;
	margin-bottom: 8px;
	padding: 2px 6px;
	scrollbar-width: none;
}
.pb-seg {
	flex: none;
	width: 140px;
	height: 7px;
	border-radius: 3px;
	background: rgba(255,255,255,.45);
	box-shadow: 0 1px 3px rgba(0,0,0,.35);
	cursor: pointer;
	transition: background .12s ease, transform .1s ease;
}
.pb-seg:hover { background: rgba(255,255,255,.95); transform: scaleX(1.06); }
.pb-seg.pb-seg-played { background: rgba(255,255,255,.2); }
.pb-seg.pb-seg-played:hover { background: rgba(255,255,255,.6); }
.pb-seg.pb-seg-current { background: var(--pb-accent); }

.pb-present-preview {
	position: absolute;
	left: 50%;
	bottom: 120px;
	transform: translateX(-50%);
	display: flex;
	flex-direction: column;
	border-radius: 10px;
	overflow: hidden;
	background: var(--pb-bg);
	box-shadow: 0 10px 34px rgba(0,0,0,.45);
	opacity: 0;
	pointer-events: none;
	transition: opacity .1s ease;
}
.pb-present-preview.pb-visible { opacity: 1; }
.pb-preview-frame {
	position: relative;
	width: 240px;
	height: 150px;
	overflow: hidden;
	background: var(--pb-bg);
}
.pb-preview-clone, .pb-preview-clone * { transition: none !important; }
.pb-preview-clone .pb-shape-frame { display: none; }
.pb-present-preview-title {
	padding: 5px 10px;
	font-size: 12px;
	color: #fff;
	background: rgba(20,20,24,.85);
	white-space: nowrap;
	overflow: hidden;
	text-overflow: ellipsis;
	max-width: 220px;
}

/* Presentation pen (temporary notes) */
.pb-present-pen {
	position: absolute;
	left: 14px;
	bottom: 14px;
	display: flex;
	flex-direction: column;
	align-items: flex-start;
	gap: 6px;
	pointer-events: auto;
}
.pb-pen-toggle {
	color: #fff;
	border-radius: 50%;
	background: rgba(20,20,24,.35);
	opacity: .4;
	transition: opacity .15s ease, background .15s ease;
}
.pb-pen-toggle:hover, .pb-pen-toggle.pb-active { opacity: 1; background: rgba(20,20,24,.6); }
.pb-present-pen .pb-btn.pb-pen-toggle.pb-active { background: var(--pb-accent); }
.pb-pen-panel {
	display: none;
	flex-direction: column;
	gap: 6px;
	padding: 6px;
	border-radius: 12px;
	color: #fff;
	background: rgba(20,20,24,.7);
	backdrop-filter: blur(8px);
	-webkit-backdrop-filter: blur(8px);
}
.pb-present-pen.pb-open .pb-pen-panel { display: flex; }
.pb-pen-panel .pb-btn { color: #fff; }
.pb-pen-panel .pb-btn:hover { background: rgba(255,255,255,.18); }
.pb-pen-tools, .pb-pen-colors, .pb-pen-row { display: flex; gap: 4px; align-items: center; }
.pb-pen-colors { padding: 0 4px; gap: 7px; }
.pb-pen-size { width: 110px; }
.pb-root.pb-pen-on .pb-zone { pointer-events: none; }
.pb-root.pb-pen-on .pb-viewport { cursor: crosshair; }
.pb-root.pb-pen-on[data-pb-pen="eraser"] .pb-viewport { cursor: cell; }
.pb-root.pb-pen-on[data-pb-pen="text"] .pb-viewport { cursor: text; }
.pb-root.pb-pen-on .pb-card * { pointer-events: none; }
.pb-root svg.pb-layer-ink path,
.pb-root svg.pb-layer-ink text { pointer-events: visiblePainted; }
.pb-ink-text { font-family: "Segoe Print", "Bradley Hand", "Comic Sans MS", cursive, sans-serif; font-weight: 600; }
.pb-present-text {
	position: absolute;
	z-index: 30;
	min-width: 160px;
	padding: 2px 6px;
	border: 2px dashed currentColor;
	border-radius: 6px;
	background: rgba(255,255,255,.85);
	font-family: "Segoe Print", "Bradley Hand", "Comic Sans MS", cursive, sans-serif;
	font-weight: 600;
	line-height: 1.2;
	resize: none;
	outline: none;
	pointer-events: auto;
}

/* Builds, exits and covers */
.pb-card, .pb-shape { transition: opacity .45s ease, box-shadow .15s ease; }
.pb-root:not(.pb-presenting) .pb-shape { transition: none; }
.pb-build-hidden, .pb-exit-hidden, .pb-occluded { opacity: 0 !important; pointer-events: none !important; }
.pb-root.pb-export { position: fixed; inset: 0; }
.pb-present-bar .pb-btn { color: #fff; border-radius: 50%; }
.pb-present-bar .pb-btn:hover { background: rgba(255,255,255,.18); }

.pb-present-info {
	display: flex;
	flex-direction: column;
	align-items: center;
	min-width: 90px;
	max-width: 40vw;
	padding: 0 8px;
	line-height: 1.2;
}
.pb-present-counter { font-variant-numeric: tabular-nums; font-weight: 600; }
.pb-present-title {
	font-size: 12px;
	opacity: .8;
	white-space: nowrap;
	overflow: hidden;
	text-overflow: ellipsis;
	max-width: 100%;
}

.pb-hint {
	left: 50%;
	top: 12px;
	transform: translateX(-50%);
	padding: 6px 14px;
	border-radius: 18px;
	font-size: 13px;
	color: #fff;
	background: rgba(20,20,24,.75);
	pointer-events: none;
	white-space: nowrap;
}
.pb-root.pb-linking .pb-viewport, .pb-root.pb-linking .pb-card { cursor: crosshair; }

/*** Image lightbox ***/

.pb-lightbox {
	position: fixed;
	inset: 0;
	z-index: 10002;
	background: rgba(10,10,14,.92);
	outline: none;
	animation: pb-fade .15s ease;
}
.pb-lightbox-stage {
	position: absolute;
	inset: 0;
	overflow: auto;
	display: flex;
	align-items: safe center;
	justify-content: safe center;
	padding: 24px;
	box-sizing: border-box;
}
.pb-lightbox-stage img {
	display: block;
	max-width: none;
	flex: none;
	cursor: zoom-out;
	box-shadow: 0 10px 40px rgba(0,0,0,.5);
	-webkit-user-drag: none;
}
.pb-lightbox-stage.pb-fit { overflow: hidden; }
.pb-lightbox-stage.pb-fit img {
	max-width: 100%;
	max-height: 100%;
	object-fit: contain;
	cursor: zoom-in;
}
.pb-lightbox-controls {
	position: absolute;
	right: 16px;
	top: 16px;
	display: flex;
	align-items: center;
	gap: 4px;
	padding: 4px;
	border-radius: 22px;
	color: #fff;
	background: rgba(20,20,24,.7);
	opacity: .5;
	transition: opacity .15s ease;
}
.pb-lightbox:hover .pb-lightbox-controls, .pb-lightbox-controls:focus-within { opacity: 1; }
@media (hover: none) { .pb-lightbox-controls { opacity: 1; } }
.pb-lightbox-controls .pb-btn { color: #fff; border-radius: 50%; }
.pb-lightbox-controls .pb-btn:hover { background: rgba(255,255,255,.18); }
.pb-lightbox-controls .pb-textbtn { background: transparent; color: #fff; border-color: rgba(255,255,255,.4); }
.pb-lightbox-zoom { min-width: 44px; text-align: center; font-size: 12px; font-variant-numeric: tabular-nums; }
.pb-modal-body img { cursor: zoom-in; }

/*** Tiddler viewer ***/

.pb-modal {
	position: fixed;
	inset: 0;
	z-index: 10001;
	height: 100vh;
	display: flex;
	align-items: center;
	justify-content: center;
	background: rgba(10, 10, 14, .55);
	backdrop-filter: blur(4px);
	-webkit-backdrop-filter: blur(4px);
	animation: pb-fade .15s ease;
}

@keyframes pb-fade { from { opacity: 0; } to { opacity: 1; } }

.pb-modal-sheet {
	position: relative;
	box-sizing: border-box;
	width: min(960px, 100vw);
	/* As tall as the tiddler needs, up to the whole screen. */
	max-height: 100vh;
	overflow-y: auto;
	border-radius: 14px;
	background: <<colour tiddler-background>>;
	color: <<colour foreground>>;
	box-shadow: 0 0 60px rgba(0,0,0,.35);
	padding: 56px clamp(18px, 6vw, 72px) 44px;
	outline: none;
}
.pb-modal-editing .pb-modal-sheet { height: 100vh; }
@media (max-width: 960px), (max-height: 600px) {
	.pb-modal-sheet { border-radius: 0; }
}

.pb-modal-controls {
	position: sticky;
	top: -40px;
	float: right;
	margin: -40px calc(-1 * clamp(10px, 4vw, 56px)) 0 0;
	display: flex;
	gap: 6px;
	z-index: 2;
	opacity: 0;
	transition: opacity .15s ease;
}

.pb-modal-sheet:hover .pb-modal-controls,
.pb-modal-controls:focus-within,
.pb-modal-editing .pb-modal-controls { opacity: 1; }

@media (hover: none) {
	.pb-modal-controls { opacity: 1; }
}

.pb-modal-btn {
	display: inline-flex;
	align-items: center;
	gap: 6px;
	height: 36px;
	padding: 0 12px;
	border: 1px solid <<colour tiddler-border>>;
	border-radius: 18px;
	background: <<colour tiddler-background>>;
	color: <<colour foreground>>;
	box-shadow: 0 2px 10px rgba(0,0,0,.12);
	cursor: pointer;
	font-size: 14px;
}
.pb-modal-btn:hover { border-color: <<colour primary>>; color: <<colour primary>>; }
.pb-modal-btn .pb-icon { width: 17px; height: 17px; }

.pb-modal-header { margin-bottom: 1em; }
.pb-modal-icon { display: inline-block; vertical-align: middle; margin-right: .4em; }
.pb-modal-icon svg, .pb-modal-icon img { width: 1.6em; height: 1.6em; }
.pb-modal-title { display: inline; margin: 0; font-size: 2.2em; line-height: 1.2; overflow-wrap: anywhere; }
.pb-modal-subtitle { color: <<colour muted-foreground>>; margin-top: .3em; }
.pb-modal-body { font-size: 1.1em; line-height: 1.6; }
.pb-modal-body img { max-width: 100%; height: auto; }
.pb-modal-missing { color: <<colour muted-foreground>>; font-style: italic; }

.pb-modal-edit {
	display: flex;
	flex-direction: column;
	gap: 10px;
	height: calc(100% - 4em);
}

.pb-modal-editor {
	width: 100%;
	min-height: 60vh;
	flex: 1;
	box-sizing: border-box;
	font-family: ui-monospace, SFMono-Regular, Menlo, Consolas, monospace;
	font-size: 15px;
	line-height: 1.5;
	padding: 12px;
	border: 1px solid <<colour tiddler-border>>;
	border-radius: 8px;
	resize: vertical;
}

@media (prefers-reduced-motion: reduce) {
	.pb-modal { animation: none; }
}

@media (max-width: 600px) {
	.pb-toolbar { left: 4px; padding: 3px; }
	.pb-btn { width: 30px; height: 30px; }
	.pb-steps { left: 10px; width: auto; }
}

/*** Story tiddlers ***/

.pb-story-outline { margin: 0 0 1em; }
.pb-story-item {
	padding: 3px 0 3px 10px;
	border-left: 3px solid <<colour primary>>;
	margin-bottom: 2px;
}
.pb-story-item.pb-story-chapter { font-weight: 600; font-size: 1.1em; margin-top: .4em; }
.pb-story-board { color: <<colour muted-foreground>>; font-size: .9em; }

.pb-dive-crumbs {
	display: flex;
	flex-wrap: wrap;
	align-items: center;
	gap: 6px;
	margin-bottom: 6px;
	font-size: 0.9em;
}
.pb-dive-crumbs .pb-dive-up { color: <<colour primary>>; }
.pb-dive-crumbs .pb-dive-up:hover { text-decoration: underline; }
.pb-dive-sep { opacity: .5; }
.pb-dive-here { font-weight: 600; }
.pb-card.pb-divable { box-shadow: 0 1px 2px rgba(0,0,0,.08), 0 6px 18px rgba(0,0,0,.10), 5px 5px 0 -1px var(--pb-panel), 5px 5px 0 0 var(--pb-border); }

.pb-story-tiddler {
	display: flex;
	flex-direction: column;
	align-items: flex-start;
	gap: 6px;
	margin: 0 0 8px;
}
.pb-story-tiddler .pb-story-field { width: 100%; }
.pb-card-menu-item {
	display: flex;
	align-items: center;
	gap: 8px;
	width: 100%;
	padding: 5px 8px;
	border: none;
	border-radius: 6px;
	background: none;
	color: var(--pb-fg);
	font-size: 13px;
	text-align: left;
	cursor: pointer;
}
.pb-card-menu-item:hover:not(:disabled) { background: var(--pb-hover, rgba(0,0,0,.06)); }
.pb-card-menu-item:disabled { opacity: .5; cursor: default; }
.pb-card-menu-item .pb-icon { width: 16px; height: 16px; flex: none; }
.pb-card-menu-item .pb-sub { margin-left: auto; color: var(--pb-muted); font-size: 11px; max-width: 110px; overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }
.pb-card-menu-item.pb-danger { color: #dc2626; }
.pb-dive-list { display: flex; flex-direction: column; gap: 2px; max-height: 240px; overflow: auto; }
.pb-dive-new { display: flex; gap: 6px; margin-top: 6px; }
.pb-dive-new .pb-input { flex: 1; min-width: 0; }
.pb-path-adds { position: relative; }
.pb-frame-wrap { position: relative; display: inline-flex; }
.pb-frame-menu {
	position: absolute;
	bottom: calc(100% + 4px);
	left: 0;
	z-index: 5;
	min-width: 150px;
	padding: 4px;
	background: var(--pb-panel);
	border: 1px solid var(--pb-border);
	border-radius: 8px;
	box-shadow: 0 6px 18px rgba(0,0,0,.14);
}
.pb-root.pb-picking .pb-card, .pb-root.pb-picking [data-pb-shape] { cursor: copy; }
.pb-story-tiddler .pb-story-buttons { display: flex; gap: 6px; flex-wrap: wrap; align-items: center; }
